class Solution {
public:
    vector<vector<int>> criticalConnections(int n, vector<vector<int>>& connections) {
        vector<vector<int>> adj(n);
        for (auto& c : connections) {
            adj[c[0]].push_back(c[1]);
            adj[c[1]].push_back(c[0]);
        }
        vector<int> disc(n, -1), low(n, 0);
        vector<vector<int>> res;
        int time = 0;
        struct Frame { int u, p, idx; };
        vector<Frame> stk;
        for (int s = 0; s < n; s++) {
            if (disc[s] != -1) continue;
            stk.push_back({s, -1, 0});
            while (!stk.empty()) {
                Frame& f = stk.back();
                int u = f.u, p = f.p;
                if (f.idx == 0) {
                    disc[u] = low[u] = ++time;
                }
                if (f.idx < (int)adj[u].size()) {
                    int v = adj[u][f.idx];
                    f.idx++;
                    if (v == p) continue;
                    if (disc[v] == -1) {
                        stk.push_back({v, u, 0});
                    } else {
                        low[u] = min(low[u], disc[v]);
                    }
                } else {
                    stk.pop_back();
                    if (!stk.empty()) {
                        int par = stk.back().u;
                        low[par] = min(low[par], low[u]);
                        if (low[u] > disc[par]) {
                            res.push_back({par, u});
                        }
                    }
                }
            }
        }
        return res;
    }
};
